     7  readstat_error_t readstat_convert(char *dst, size_t dst_len, const char *src, size_t src_len, iconv_t converter) {
     8      /* strip off spaces from the input because the programs use ASCII space
     9       * padding even with non-ASCII encoding. */
    10      while (src_len && src[src_len-1] == ' ') {
    11          src_len--;
    12      }
    13      if (dst_len == 0) {
    14          return READSTAT_ERROR_CONVERT_LONG_STRING;
    15      } else if (converter) {
    16          size_t dst_left = dst_len - 1;
    17          char *dst_end = dst;
    18          size_t status = iconv(converter, (readstat_iconv_inbuf_t)&src, &src_len, &dst_end, &dst_left);
    19          if (status == (size_t)-1) {
    20              if (errno == E2BIG) {
    21                  return READSTAT_ERROR_CONVERT_LONG_STRING;
    22              } else if (errno == EILSEQ) {
    23                  return READSTAT_ERROR_CONVERT_BAD_STRING;
    24              } else if (errno != EINVAL) { /* EINVAL indicates improper truncation; accept it */
    25                  return READSTAT_ERROR_CONVERT;
    26              }
    27          }
    28          dst[dst_len - dst_left - 1] = '\0';
    29      } else if (src_len + 1 > dst_len) {
    30          return READSTAT_ERROR_CONVERT_LONG_STRING;
    31      } else {
    32          memcpy(dst, src, src_len);
    33          dst[src_len] = '\0';
    34      }
    35      return READSTAT_OK;
