   682  static readstat_error_t sav_process_row(unsigned char *buffer, size_t buffer_len, sav_ctx_t *ctx) {
   683      if (ctx->row_offset) {
   684          ctx->row_offset--;
   685          return READSTAT_OK;
   686      }
   687
   688      readstat_error_t retval = READSTAT_OK;
   689      double fp_value;
   690      int offset = 0;
   691      readstat_off_t data_offset = 0;
   692      size_t raw_str_used = 0;
   693      int segment_offset = 0;
   694      int var_index = 0, col = 0;
   695      int raw_str_is_utf8 = ctx->input_encoding && !strcmp(ctx->input_encoding, "UTF-8");
   696
   697      while (data_offset < buffer_len && col < ctx->var_index && var_index < ctx->var_index) {
   698          spss_varinfo_t *col_info = ctx->varinfo[col];
   699          spss_varinfo_t *var_info = ctx->varinfo[var_index];
   700          readstat_value_t value = { .type = var_info->type };
   701          if (offset > 31) {
   702              retval = READSTAT_ERROR_PARSE;
   703              goto done;
   704          }
   705          if (var_info->type == READSTAT_TYPE_STRING) {
   706              if (raw_str_used + 8 <= ctx->raw_string_len) {
   707                  if (raw_str_is_utf8) {
   708                      /* Skip null bytes, see https://github.com/tidyverse/haven/issues/560  */
   709                      char c;
   710                      for (int i=0; i<8; i++)
   711                          if ((c = buffer[data_offset+i]))
   712                              ctx->raw_string[raw_str_used++] = c;
   713                  } else {
   714                      memcpy(ctx->raw_string + raw_str_used, &buffer[data_offset], 8);
   715                      raw_str_used += 8;
   716                  }
   717              }
   718              if (++offset == col_info->width) {
   719                  if (++segment_offset < var_info->n_segments) {
   720                      raw_str_used--;
   721                  }
   722                  offset = 0;
   723                  col++;
   724              }
   725              if (segment_offset == var_info->n_segments) {
   726                  if (!ctx->variables[var_info->index]->skip) {
   727                      retval = readstat_convert(ctx->utf8_string, ctx->utf8_string_len,
   728                              ctx->raw_string, raw_str_used, ctx->converter);
   729                      if (retval != READSTAT_OK)
   730                          goto done;
   731                      value.v.string_value = ctx->utf8_string;
   732                      if (ctx->handle.value(ctx->current_row, ctx->variables[var_info->index],
   733                                  value, ctx->user_ctx) != READSTAT_HANDLER_OK) {
   734                          retval = READSTAT_ERROR_USER_ABORT;
   735                          goto done;
   736                      }
   737                  }
   738                  raw_str_used = 0;
   739                  segment_offset = 0;
   740                  var_index += var_info->n_segments;
   741              }
   742          } else if (var_info->type == READSTAT_TYPE_DOUBLE) {
   743              if (!ctx->variables[var_info->index]->skip) {
   744                  memcpy(&fp_value, &buffer[data_offset], 8);
   745                  if (ctx->bswap) {
   746                      fp_value = byteswap_double(fp_value);
   747                  }
   748                  value.v.double_value = fp_value;
   749                  sav_tag_missing_double(&value, ctx);
   750                  if (ctx->handle.value(ctx->current_row, ctx->variables[var_info->index],
   751                              value, ctx->user_ctx) != READSTAT_HANDLER_OK) {
   752                      retval = READSTAT_ERROR_USER_ABORT;
   753                      goto done;
   754                  }
   755              }
   756              var_index += var_info->n_segments;
   757              col++;
   758          }
   759          data_offset += 8;
   760      }
   761      ctx->current_row++;
   762  done:
   763      return retval;
   764  }
