   766  static readstat_error_t sav_read_data(sav_ctx_t *ctx) {
   767      readstat_error_t retval = READSTAT_OK;
   768      size_t longest_string = 256;
   769      int i;
   770
   771      for (i=0; i<ctx->var_index;) {
   772          spss_varinfo_t *info = ctx->varinfo[i];
   773          if (info->string_length > longest_string) {
   774              longest_string = info->string_length;
   775          }
   776          i += info->n_segments;
   777      }
   778
   779      ctx->raw_string_len = longest_string + sizeof(SAV_EIGHT_SPACES)-2;
   780      ctx->raw_string = readstat_malloc(ctx->raw_string_len);
   781
   782      ctx->utf8_string_len = 4*longest_string+1 + sizeof(SAV_EIGHT_SPACES)-2;
   783      ctx->utf8_string = readstat_malloc(ctx->utf8_string_len);
   784
   785      if (ctx->raw_string == NULL || ctx->utf8_string == NULL) {
   786          retval = READSTAT_ERROR_MALLOC;
   787          goto done;
   788      }
   789
   790      if (ctx->compression == READSTAT_COMPRESS_ROWS) {
   791          retval = sav_read_compressed_data(ctx, &sav_process_row);
   792      } else if (ctx->compression == READSTAT_COMPRESS_BINARY) {
   793  #if HAVE_ZLIB
   794          retval = zsav_read_compressed_data(ctx, &sav_process_row);
   795  #else
   796          retval = READSTAT_ERROR_UNSUPPORTED_COMPRESSION;
   797  #endif
   798      } else {
   799          retval = sav_read_uncompressed_data(ctx, &sav_process_row);
   800      }
   801      if (retval != READSTAT_OK)
   802          goto done;
   803
   804      if (ctx->record_count >= 0 && ctx->current_row != ctx->row_limit) {
   805          retval = READSTAT_ERROR_ROW_COUNT_MISMATCH;
   806      }
   807
   808  done:
   809      return retval;
   810  }
