   812  static readstat_error_t sav_read_uncompressed_data(sav_ctx_t *ctx,
   813          readstat_error_t (*row_handler)(unsigned char *, size_t, sav_ctx_t *)) {
   814      readstat_error_t retval = READSTAT_OK;
   815      readstat_io_t *io = ctx->io;
   816      unsigned char *buffer = NULL;
   817      size_t bytes_read = 0;
   818      size_t buffer_len = ctx->var_offset * 8;
   819
   820      buffer = readstat_malloc(buffer_len);
   821
   822      if (ctx->row_offset) {
   823          if (io->seek(buffer_len * ctx->row_offset, READSTAT_SEEK_CUR, io->io_ctx) == -1) {
   824              retval = READSTAT_ERROR_SEEK;
   825              goto done;
   826          }
   827          ctx->row_offset = 0;
   828      }
   829
   830      while (ctx->row_limit == -1 || ctx->current_row < ctx->row_limit) {
   831          retval = sav_update_progress(ctx);
   832          if (retval != READSTAT_OK)
   833              goto done;
   834
   835          if ((bytes_read = io->read(buffer, buffer_len, io->io_ctx)) != buffer_len)
   836              goto done;
   837
   838          retval = row_handler(buffer, buffer_len, ctx);
   839          if (retval != READSTAT_OK)
   840              goto done;
   841      }
   842  done:
   843      if (buffer)
   844          free(buffer);
   845
   846      return retval;
   847  }
