   149  static void sav_tag_missing_double(readstat_value_t *value, sav_ctx_t *ctx) {
   150      double fp_value = value->v.double_value;
   151      uint64_t long_value = 0;
   152      memcpy(&long_value, &fp_value, 8);
   153      if (long_value == ctx->missing_double)
   154          value->is_system_missing = 1;
   155      if (long_value == ctx->lowest_double)
   156          value->is_system_missing = 1;
   157      if (long_value == ctx->highest_double)
   158          value->is_system_missing = 1;
   159      if (isnan(fp_value))
   160          value->is_system_missing = 1;
   161  }
