   168  static readstat_error_t sav_skip_variable_record(sav_ctx_t *ctx) {
   169      sav_variable_record_t variable;
   170      readstat_error_t retval = READSTAT_OK;
   171      readstat_io_t *io = ctx->io;
   172      if (io->read(&variable, sizeof(sav_variable_record_t), io->io_ctx) < sizeof(sav_variable_record_t)) {
   173          retval = READSTAT_ERROR_READ;
   174          goto cleanup;
   175      }
   176      if (variable.has_var_label) {
   177          uint32_t label_len;
   178          if (io->read(&label_len, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
   179              retval = READSTAT_ERROR_READ;
   180              goto cleanup;
   181          }
   182          label_len = ctx->bswap ? byteswap4(label_len) : label_len;
   183          uint32_t label_capacity = (label_len + 3) / 4 * 4;
   184          if (io->seek(label_capacity, READSTAT_SEEK_CUR, io->io_ctx) == -1) {
   185              retval = READSTAT_ERROR_SEEK;
   186              goto cleanup;
   187          }
   188      }
   189      if (variable.n_missing_values) {
   190          int n_missing_values = ctx->bswap ? byteswap4(variable.n_missing_values) : variable.n_missing_values;
   191          if (io->seek(abs(n_missing_values) * sizeof(double), READSTAT_SEEK_CUR, io->io_ctx) == -1) {
   192              retval = READSTAT_ERROR_SEEK;
   193              goto cleanup;
   194          }
   195      }
   196  cleanup:
   197      return retval;
   198  }
