   200  static readstat_error_t sav_read_variable_label(spss_varinfo_t *info, sav_ctx_t *ctx) {
   201      readstat_io_t *io = ctx->io;
   202      readstat_error_t retval = READSTAT_OK;
   203      uint32_t label_len, label_capacity;
   204      size_t out_label_len;
   205      char *label_buf = NULL;
   206      if (io->read(&label_len, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
   207          retval = READSTAT_ERROR_READ;
   208          goto cleanup;
   209      }
   210      label_len = ctx->bswap ? byteswap4(label_len) : label_len;
   211
   212      if (label_len == 0)
   213          goto cleanup;
   214
   215      label_capacity = (label_len + 3) / 4 * 4;
   216      if ((label_buf = readstat_malloc(label_capacity)) == NULL) {
   217          retval = READSTAT_ERROR_MALLOC;
   218          goto cleanup;
   219      }
   220
   221      out_label_len = (size_t)label_len*4+1;
   222      if ((info->label = readstat_malloc(out_label_len)) == NULL) {
   223          retval = READSTAT_ERROR_MALLOC;
   224          goto cleanup;
   225      }
   226
   227      if (io->read(label_buf, label_capacity, io->io_ctx) < label_capacity) {
   228          retval = READSTAT_ERROR_READ;
   229          goto cleanup;
   230      }
